[Authorize(Policy = "RequireDocumentAccess")]
public async Task<IActionResult> GetDocument(string documentId)
{
    // Access granted by policy handler
    var doc = await _service.GetDocumentAsync(documentId);
    return Ok(doc);
}

public class DocumentsController : ControllerBase
{
    private readonly IAuthorizationService _authService;

    public DocumentsController(IAuthorizationService authService)
    {
        _authService = authService;
    }

    [HttpPut("{id}")]
    public async Task<IActionResult> UpdateDocument(string id, UpdateDto dto)
    {
        var document = await _dbContext.Documents.FindAsync(id);
        if (document == null) return NotFound();

        // Authorize based on the actual resource
        var result = await _authService.AuthorizeAsync(
            User, document, "CanEditDocument");

        if (!result.Succeeded)
        {
            return Forbid();
        }

        document.Title = dto.Title;
        document.Content = dto.Content;
        await _dbContext.SaveChangesAsync();
        return NoContent();
    }
}
